 async function save(table,payload){if(!db||saving)return;setSaving(true);setNotice(editingRecord?'Memperbarui data...':'Menyimpan data...');try{const query=editingRecord?db.from(table).update(payload).eq('id',editingRecord.id):db.from(table).insert(payload);const {error}=await query;if(error)throw error;setShowForm(false);setForm({});setEditingRecord(null);setNotice(editingRecord?'Data berhasil diperbarui':'Data berhasil disimpan');await loadAll()}catch(e){setError(e.message);setNotice('Gagal menyimpan data')}finally{setSaving(false)}}
 async function deleteRecord(table,item,label){if(!await askConfirm('Konfirmasi penghapusan','Apakah '+label+' ini akan dihapus? Data yang dihapus tidak dapat dipulihkan.'))return;setSaving(true);setNotice('Menghapus data...');try{const {error}=await db.from(table).delete().eq('id',item.id);if(error)throw error;setNotice(label+' berhasil dihapus');await loadAll()}catch(e){setError(e.message);setNotice('Gagal menghapus '+label)}finally{setSaving(false)}}
 function editRecord(type,item){setEditingRecord(item);setForm({...item});setShowForm(type)}
 async function createAnnouncement(){
  if(saving)return;
  setSaving(true);setError('');setNotice('Menyimpan pengumuman...');
  const uploadedPaths=[];
  try{
   const uploadMedia=async(file,kind)=>{
    if(!file)return null;
    const allowed=kind==='image'?['image/jpeg','image/png','image/webp']:['video/mp4','video/webm','video/quicktime'];
    const limit=kind==='image'?5*1024*1024:50*1024*1024;
    if(!allowed.includes(file.type))throw new Error(kind==='image'?'Format gambar harus JPG, PNG, atau WEBP.':'Format video harus MP4, WEBM, atau MOV.');
    if(file.size>limit)throw new Error(kind==='image'?'Ukuran gambar maksimal 5 MB.':'Ukuran video maksimal 50 MB.');
    const ext=(file.name.split('.').pop()|| (kind==='image'?'jpg':'mp4')).toLowerCase();
    const path='announcements/'+kind+'-'+Date.now()+'-'+Math.random().toString(36).slice(2)+'.'+ext;
    const {data,error}=await db.storage.from('announcement-images').upload(path,file,{contentType:file.type,upsert:false});
    if(error)throw new Error('Upload '+kind+' gagal: '+error.message);
    uploadedPaths.push(path);
    const {data:{publicUrl}}=db.storage.from('announcement-images').getPublicUrl(data.path||path);
    if(!publicUrl)throw new Error('URL publik '+kind+' tidak berhasil dibuat.');
    return publicUrl;
   };
   const image_url=form.imageFile?await uploadMedia(form.imageFile,'image'):(editingRecord?.image_url||null);
   const video_url=form.videoFile?await uploadMedia(form.videoFile,'video'):(editingRecord?.video_url||null);
   const payload={title:(form.title||'').trim(),body:(form.body||'').trim()||(form.title||'').trim(),image_url,video_url};
   if(!payload.title)throw new Error('Judul pengumuman wajib diisi.');
   let result;
   if(editingRecord?.id) result=await db.from('announcements').update(payload).eq('id',editingRecord.id);
   else result=await db.from('announcements').insert({...payload,created_by:session.user.id});
   if(result.error)throw result.error;
   setShowForm(false);setForm({});setEditingRecord(null);
   setNotice(editingRecord?'Pengumuman berhasil diperbarui':'Pengumuman berhasil diterbitkan');
   await loadAll();
  }catch(e){
   setError('Gagal menyimpan pengumuman: '+(e?.message||String(e)));
   setNotice('Pengumuman belum tersimpan');
  }finally{setSaving(false)}
 }

